// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.local/** * NOUS — llama.cpp JNI Bridge. * * Kotlin-side JNI declarations for llama.cpp native library. * The C++ implementation lives in `:native:llamacpp/src/main/cpp/jarvis_llm.cpp`. * * ## v2.1 Features *   - mmap memory mapping (prevents OOM for large models) *   - Async-signal-safe crash handler (pipe + watchdog, NOT JVM call) *   - Zero-copy token streaming (token IDs, NOT strings) *   - Barge-in via `g_should_stop` atomic flag *   - KV cache context shifting *   - Lookahead decoding (no draft model needed) * * ## Native Library Loading * * Loaded lazily on first use. If library not found (dev build without * pre-built .so), all methods throw `UnsatisfiedLinkError` — caught by * [LlamaCppProvider] which returns a graceful error. * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§4 Local LLM</a> */object LlamaCppJni {    @Volatile    private var loaded: Boolean = false    @Volatile    private var loadFailed: Boolean = false    /**     * Load the native library. Safe to call multiple times.     * @return true if loaded successfully, false if library not available     */    @Synchronized    fun ensureLoaded(): Boolean {        if (loaded) return true        if (loadFailed) return false        return try {            System.loadLibrary("jarvis_llm")            loaded = true            true        } catch (e: UnsatisfiedLinkError) {            loadFailed = true            false        } catch (e: SecurityException) {            loadFailed = true            false        }    }    /** Check if the native library is loaded. */    fun isLoaded(): Boolean = loaded    /** Reset the load state (for testing). */    internal fun resetLoadState() {        loaded = false        loadFailed = false    }    // ─── JNI Declarations ───────────────────────────────────────────    /**     * Initialize a llama.cpp context with the given model.     *     * @param modelPath absolute path to the .gguf model file     * @param useGpu whether to use GPU (Vulkan) acceleration     * @param useMmap whether to use mmap (memory-mapped file I/O)     * @param contextLength max context window in tokens     * @return native context pointer (> 0) or 0 on failure     */    @JvmStatic    external fun nativeInitContext(        modelPath: String,        useGpu: Boolean,        useMmap: Boolean,        contextLength: Int,    ): Long    /**     * Free a llama.cpp context.     * @param contextPtr native context pointer from [nativeInitContext]     */    @JvmStatic    external fun nativeFreeContext(contextPtr: Long)    /**     * Generate text with streaming token callback.     *     * Uses zero-copy token IDs (jint array) for performance — avoids     * creating jstring objects per token. The callback receives token     * IDs which are decoded on the Kotlin side.     *     * @param contextPtr native context pointer     * @param prompt the full prompt (system + context + user input)     * @param maxTokens maximum tokens to generate     * @param temperature sampling temperature (0.0-2.0)     * @param topP nucleus sampling threshold (0.0-1.0)     * @param topK top-k sampling (1-100)     * @param repeatPenalty repetition penalty (0.5-2.0)     * @param seed random seed (-1 for random)     * @return generated text, or empty string on failure     */    @JvmStatic    external fun nativeGenerate(        contextPtr: Long,        prompt: String,        maxTokens: Int,        temperature: Float,        topP: Float,        topK: Int,        repeatPenalty: Float,        seed: Long,    ): String    /**     * Generate text with per-token streaming callback.     *     * The callback [onToken] is called from native code for each generated     * token. Uses jint token IDs for zero-copy performance.     *     * @param contextPtr native context pointer     * @param prompt the full prompt     * @param maxTokens maximum tokens     * @param temperature sampling temperature     * @param topP nucleus sampling     * @param topK top-k sampling     * @param repeatPenalty repetition penalty     * @param seed random seed     * @param onToken callback (tokenId: Int) → Boolean (true = continue, false = stop)     * @return generated text     */    @JvmStatic    external fun nativeGenerateStream(        contextPtr: Long,        prompt: String,        maxTokens: Int,        temperature: Float,        topP: Float,        topK: Int,        repeatPenalty: Float,        seed: Long,        onToken: (Int) -> Boolean,    ): String    /**     * Stop generation (barge-in). Sets `g_should_stop` atomic flag.     * Called from Kotlin when user interrupts (CancellationToken.cancel).     */    @JvmStatic    external fun nativeStopGeneration(contextPtr: Long)    /**     * Generate embedding for a text.     * @return float array (384-dim or model-specific dimension)     */    @JvmStatic    external fun nativeEmbed(contextPtr: Long, text: String): FloatArray    /**     * Get the model's native sample rate (always 16000 for whisper).     */    @JvmStatic    external fun nativeGetContextLength(contextPtr: Long): Int    /**     * Get model metadata (architecture, quantization, parameters).     * @return JSON string with metadata     */    @JvmStatic    external fun nativeGetModelInfo(modelPath: String): String    /**     * Check if Vulkan GPU is available on this device.     * @return true if GPU acceleration is possible     */    @JvmStatic    external fun nativeIsGpuAvailable(): Boolean    /**     * Get available GPU VRAM in MB.     * @return VRAM in MB (0 if no GPU)     */    @JvmStatic    external fun nativeGetGpuVramMb(): Int    /**     * Install native crash handler (async-signal-safe: pipe + watchdog).     * Called once at app startup. If llama.cpp crashes (SIGSEGV/SIGABRT),     * the handler writes crash info to a pipe (NOT to JVM — that's not     * async-signal-safe). A separate watchdog process reads the pipe and     * logs the crash.     */    @JvmStatic    external fun nativeInstallCrashHandler(logDir: String)    // ─── KV Cache Reuse (Strategy §4.4) ──────────────────────────────    /**     * Get the current KV cache prefix hash.     *     * Strategy §4.4: "A prefix hash tracks which prompts are cached."     * Returns the hash of the prompt prefix currently in the KV cache.     * If the new prompt shares this prefix, only the new tokens need to be computed.     *     * @param contextPtr native context pointer     * @return hash of the cached prefix (0 if no cache)     */    @JvmStatic    external fun nativeGetKvCachePrefixHash(contextPtr: Long): Long    /**     * Set the KV cache prefix for reuse.     *     * Strategy §4.4: "KV cache reuse caches common prompt prefixes (system prompt,     * persona definition) to save 40-60% compute on follow-up queries."     *     * If the new prompt starts with the cached prefix, only the new tokens     * are computed. This is the key optimization for multi-turn conversations.     *     * @param contextPtr native context pointer     * @param prefixHash hash of the prefix to cache (0 = clear cache)     */    @JvmStatic    external fun nativeSetKvCachePrefixHash(contextPtr: Long, prefixHash: Long)    /**     * Remove old tokens from the KV cache (context shifting).     *     * Strategy §4.4: "Context shifting handles context overflow gracefully:     * when the conversation exceeds the model's context window, llama_kv_cache_seq_rm     * removes the oldest tokens from the KV cache (shifting the window forward)     * instead of hard-failing."     *     * @param contextPtr native context pointer     * @param nKeep number of tokens to keep at the beginning (system prompt)     * @param nShift number of tokens to remove from the middle     */    @JvmStatic    external fun nativeShiftKvCache(contextPtr: Long, nKeep: Int, nShift: Int)    // ─── LoRA Adapter Support (Strategy §4.8) ───────────────────────    /**     * Load a LoRA adapter onto an existing model context.     *     * Strategy §4.8: "LoRA (Low-Rank Adaptation) allows fine-tuning the base     * model for specific tasks without retraining the full model. A LoRA adapter     * is ~20MB, so multiple adapters can be stored and hot-swapped at runtime."     *     * @param contextPtr native context pointer (model must already be loaded)     * @param loraPath path to the .gguf LoRA adapter file     * @param scale scaling factor for the adapter (1.0 = full strength, 0.5 = half)     * @return adapter handle (>0 on success, 0 on failure)     */    @JvmStatic    external fun nativeLoadLoraAdapter(contextPtr: Long, loraPath: String, scale: Float): Long    /**     * Unload a LoRA adapter from a model context.     *     * Strategy §4.8: "The JNI bridge supports loading/unloading adapters without     * reloading the base model — swap takes ~500ms vs 5 seconds for a full reload."     *     * @param contextPtr native context pointer     * @param adapterHandle adapter handle from [nativeLoadLoraAdapter]     * @return true on success     */    @JvmStatic    external fun nativeUnloadLoraAdapter(contextPtr: Long, adapterHandle: Long): Boolean    /**     * List all loaded LoRA adapters on a context.     *     * @param contextPtr native context pointer     * @return JSON array of adapter handles + paths     */    @JvmStatic    external fun nativeListLoraAdapters(contextPtr: Long): String}